  "news.date": "Die Schlagzeilen von heute · Tag {day}",
  "news.h0": "Nach langem Stromausfall ist das Licht zurück",
  "news.b0": "Die Bewohner von Mushin jubelten, als der Strom nach einem Tag Dunkelheit zurückkam. Die Generatoren wurden endlich still.",
  "news.h1": "Schlange an der Tankstelle ist einen Kilometer lang",
  "news.b1": "Autofahrer warten stundenlang. Manche kaufen inzwischen am Straßenrand.",
  "news.h2": "Danfo-Fahrer verkünden einen neuen Fahrpreis",
  "news.b2": "Fahrgäste fragen, warum der Fahrpreis sich immer ändert, wenn es regnet.",
  "news.h3": "Starkregen überflutet tiefer liegende Straßen",
  "news.b3": "Die Abflüsse waren wieder verstopft. Anwohner sollen die Autos wegfahren und drinnen bleiben.",
  "news.h4": "Lokales Team gewinnt auf dem Platz im Unity Park",
  "news.b4": "Ein Tor in letzter Minute ließ die Menge rennen. Die Dame-Meister sahen aus dem Schatten zu.",
  "news.h5": "Neue Afrobeat-Single stürmt die Charts",
  "news.b5": "Bis zum Mittag hat sie ganz Lagos zweimal gehört. Der Tanz läuft schon in jeder Straße.",
  "news.h6": "Neue Wohnanlage entsteht in Lekki",
  "news.b6": "Wieder Kräne am Horizont. Makler sagen, die Wohnungen sind verkauft, bevor die Farbe trocken ist.",
  "news.h7": "Marktleute freuen sich über günstigere Tomaten",
  "news.b7": "Nach einer schweren Saison fallen die Preise endlich. Tante Funke sagt, man soll nicht zu früh feiern.",
  "news.h8": "Lagoon University bietet Abendkurse an",
  "news.b8": "Studierende sagen, die Vorlesungen seien billiger als die Daten, sie herunterzuladen.",
  "news.h9": "Krankenhaus bietet einen kostenlosen Vorsorgetag an",
  "news.b9": "Lange Schlangen, freundliche Pflegekräfte und viele Leute, die ihren Blutdruck erfahren.",
  "news.h10": "Anwohner pflanzen Bäume an der Straße",
  "news.b10": "Neben der vielbefahrenen Straße wächst ein grüner Streifen. Die Ziege hat schon einen probiert.",
  "news.h11": "Solarlampen für drei Straßen eingetroffen",
  "news.b11": "Die Nachbarn sagen, mit den neuen Lampen fühlt sich der Heimweg nachts sicher an.",
