  "chapter.1.title": "Bescheidene Anfänge",
  "chapter.1.blurb": "Ein kleines Zimmer in Mushin, ein paar Naira und ein großer Traum.",
  "chapter.2.title": "Fuß fassen",
  "chapter.2.blurb": "Miete, ein erster Job, neue Freunde und die ersten schweren Entscheidungen.",
  "chapter.3.title": "Der Hustle",
  "chapter.3.blurb": "Geld, Fähigkeiten, Überschwemmungen und NEPA. Lagos stellt dich auf die Probe.",
  "chapter.4.title": "Deine Zukunft wählen",
  "chapter.4.blurb": "Fünf Mentoren, fünf Wege. Wähl das Leben, das du willst.",
  "chapter.5.title": "Einen Namen machen",
  "chapter.5.blurb": "Die Leute kennen deinen Namen. Halt ihn sauber.",
  "chapter.6.title": "Größere Chancen",
  "chapter.6.blurb": "Investitionen, Beförderungen und Entscheidungen mit echtem Gewicht.",
  "chapter.7.title": "Der Preis des Erfolgs",
  "chapter.7.blurb": "Rivalen, Rückschläge und Entscheidungen, die niemand sonst sieht.",
  "chapter.8.title": "Spuren hinterlassen",
  "chapter.8.blurb": "Menschen führen, deine Straße prägen, deinen Namen wachsen lassen.",
  "chapter.9.title": "Ganz oben",
  "chapter.9.blurb": "Die größte Bühne deiner Karriere. Alles steht auf dem Spiel.",
  "chapter.10.title": "Dein Vermächtnis",
  "chapter.10.blurb": "Woran wird sich Lagos bei dir erinnern?",
