  "homegoals.title": "Wohnziele ({done}/{n})",
  "homegoals.lede": "Bau deine Wohnung, deinen Hof und deine Autos aus. Hol dir für jedes Ziel eine Belohnung. Jedes eröffnet eine Geschichte in der 📖 Story-App.",
  "homegoals.locked": "Öffnet sich in Kapitel {n} der Geschichte.",
  "homegoals.claim": "Belohnung abholen",
  "homegoals.claimed": "Abgeholt. Schau in 📖 Story nach der neuen Geschichte.",
  "homegoal.settle.name": "Einrichten",
  "homegoal.settle.desc": "Eine Wohnung wird erst mit Möbeln zum Zuhause. Füll sie.",
  "homegoal.colour.name": "Mach es zu deinem",
  "homegoal.colour.desc": "Verlege neue Böden und versetze eine Wand. Dein Geschmack, deine Wohnung.",
  "homegoal.yard.name": "Der Hof gehört dir",
  "homegoal.yard.desc": "Mit Einfahrt und Garten wird aus einem Gelände ein Vorgarten.",
  "homegoal.wheels.name": "Das erste Auto",
  "homegoal.wheels.desc": "Kauf dein erstes Fahrzeug und parke es zu Hause.",
  "homegoal.extend.name": "Platz zum Wachsen",
  "homegoal.extend.desc": "Bau einen Anbau: Arbeitszimmer, Gästezimmer, Essbereich.",
  "homegoal.duplex.name": "Wohnen auf zwei Etagen",
  "homegoal.duplex.desc": "Erst ein Balkon, dann ein ganzes zweites Stockwerk.",
  "homegoal.garage.name": "Eine richtige Garage",
  "homegoal.garage.desc": "Eine überdachte Garage und zwei Fahrzeuge für die Einfahrt.",
  "homegoal.mansion.name": "Das große Haus",
  "homegoal.mansion.desc": "Zweites Stockwerk, Garage, Pool und der größte Anbau. Das ganze Anwesen.",
  "mission.side-housewarming.title": "Einweihungsfeier",
  "mission.side-housewarming.goal": "Stell zehn weitere Dinge in deine Wohnung und nimm eine Einladung fürs Wochenende an.",
  "mission.side-housewarming.intro": "Die Wohnung sieht endlich bewohnt aus. Mama erfährt es, bevor du es ihr sagst, wie Mütter das eben tun, und kündigt an, mit einem Topf Jollof vorbeizukommen.",
  "mission.side-housewarming.line0": "Ein Sofa, eine Lampe, ein richtiger Tisch. Schau dich an, du baust dir ein Leben auf. Dein Vater hätte den ganzen Tag auf diesem Sofa gesessen.",
  "mission.side-housewarming.line1": "Mama, bitte, das Sofa ist für Gäste.",
  "mission.side-housewarming.choice0": "Mama bitten, die Wohnung zu segnen",
  "mission.side-housewarming.result0": "Sie geht durch jeden Raum, summt und berührt jede Wand. Die Wohnung fühlt sich an, als wäre sie schon seit Jahren da.",
  "mission.side-housewarming.choice1": "Eine kleine Party für die Nachbarschaft schmeißen",
  "mission.side-housewarming.result1": "Nach vierzig Minuten ist der halbe Hof in deinem Wohnzimmer. Die Box ist geliehen, der Reis reicht nicht, und es ist allen egal.",
  "mission.side-garden.title": "Das Tor und die Gartenparty",
  "mission.side-garden.goal": "Bau die Hofmauer mit Tor und nimm zwei Einladungen an.",
  "mission.side-garden.intro": "Du hast Tobi, den Architekten, auf der Insel kennengelernt. Er sieht deinen neuen Garten und zuckt zusammen und lächelt zugleich. „Schöner Rasen. Aber jeder kann einfach hereinspazieren. Gib dem Gelände eine Mauer und ein Tor, dann helfe ich dir beim Feiern.“",
  "mission.side-garden.line0": "Bei einem Tor geht es nicht darum, Leute draußen zu halten. Es geht darum, zu entscheiden, wen du hereinlässt. Das ist die ganze Architektur.",
  "mission.side-garden.line1": "Das klingt wie etwas, das man auf einer Hochzeit sagt.",
  "mission.side-garden.choice0": "Tobi das Layout der Party planen lassen",
  "mission.side-garden.result0": "Laternen entlang der Einfahrt, Stühle im Bogen, ein Lichtweg zum Tor. Die Gäste fragen ständig, wer das gemacht hat.",
  "mission.side-garden.choice1": "Einfach bleiben: Grill, Musik, Nachbarn",
  "mission.side-garden.result1": "Suya-Rauch über dem neuen Rasen, der Cousin von irgendwem an den Boxen. Einfach und perfekt.",
  "mission.side-roadtrip.title": "Die erste Spritztour",
  "mission.side-roadtrip.goal": "Mach drei Fahrten quer durch die Stadt und unternimm etwas am Sunset Beach.",
  "mission.side-roadtrip.intro": "Ein Auto in der Einfahrt, und Tunde kann nicht aufhören, es anzustarren. „Wir lassen das nicht rumstehen. Sunset Beach. Drei Stopps unterwegs. Den gerösteten Mais zahle ich.“",
  "mission.side-roadtrip.line0": "Fenster runter, Musik laut, kein Stau in Sicht. Dafür war das Geld da.",
  "mission.side-roadtrip.line1": "Das Geld war für die Miete, Tunde.",
  "mission.side-roadtrip.line2": "Die Miete ist für morgen. Heute haben wir ein Meer.",
  "mission.side-roadtrip.choice0": "Langsam und vorsichtig nach Hause fahren",
  "mission.side-roadtrip.result0": "Tunde meckert die ersten zehn Minuten, dann schläft er ein. Du parkst ohne einen Kratzer.",
  "mission.side-roadtrip.choice1": "Den Sonnenuntergang zurück überholen",
  "mission.side-roadtrip.result1": "Du erreichst das Tor mit dem letzten orangen Licht und einem sehr lauten Motor. Die Nachbarn reden wochenlang darüber.",
  "mission.side-guestroom.title": "Das Gästezimmer",
  "mission.side-guestroom.goal": "Richte deine Wohnung mit insgesamt vierzehn Dingen ein und werde Mama näher.",
  "mission.side-guestroom.intro": "Der Anbau ist fertig. Mama wirft einen Blick auf das neue Zimmer, und ihre Augen leuchten. „Jetzt muss Kunle nicht mehr auf der Matte bei seinem Freund schlafen. Und ich kann eine ganze Woche zu Besuch kommen.“",
  "mission.side-guestroom.line0": "Ein Bett für Gäste, ein Platz für Kunle zum Lernen und ein Fenster, das sich öffnen lässt. Du hast es gut gemacht, mein Kind.",
  "mission.side-guestroom.line1": "Es war nicht billig, Mama.",
  "mission.side-guestroom.line2": "Nichts, was sich zu behalten lohnt, ist es.",
  "mission.side-guestroom.choice0": "Kunle das Zimmer für seine Prüfungen anbieten",
  "mission.side-guestroom.result0": "Kunle lernt dort einen Monat lang. Er besteht. Er hört nie auf, von dem Tisch am Fenster zu schwärmen.",
  "mission.side-guestroom.choice1": "Als Arbeitszimmer für dein eigenes Geschäft behalten",
  "mission.side-guestroom.result1": "Ein Schreibtisch, eine Lampe, eine Tür, die sich schließt. In einer Woche schaffst du mehr als im Monat davor.",
